// Normalize telemetry output to ThingsBoard flat JSON format
// Input: msg.payload = {key1: val1, key2: val2, ...}
// Input: msg.timestamp (optional, epoch_ms)
// Output: msg.payload = {"ts": <epoch_ms>, "values": {key1: val1, ...}}

const values = {};
const raw = msg.payload;

if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
    node.error('[protocol-normalization] InvalidPayload: expected object, got ' + typeof raw, msg);
    return null;
}

for (const [key, val] of Object.entries(raw)) {
    // Validate key format: snake_case (at least one underscore)
    if (!/^[a-z][a-z0-9]*(_[a-z0-9]+)+$/.test(key)) {
        node.warn('[protocol-normalization] InvalidKey: "' + key + '" does not match snake_case_unit pattern, skipping');
        continue;
    }

    // Coerce string numbers to float
    if (typeof val === 'string') {
        const num = parseFloat(val);
        if (!isNaN(num)) {
            values[key] = num;
        } else {
            values[key] = val;
        }
    } else if (typeof val === 'number' && isFinite(val)) {
        values[key] = val;
    } else if (typeof val === 'boolean') {
        values[key] = val;
    } else {
        node.warn('[protocol-normalization] InvalidValue: key "' + key + '" has unsupported type, skipping');
        continue;
    }
}

if (Object.keys(values).length === 0) {
    node.error('[protocol-normalization] EmptyPayload: no valid telemetry keys after normalization', msg);
    return null;
}

const ts = msg.timestamp || Date.now();

msg.payload = {
    ts: ts,
    values: values
};

// Set output topic if provided
if (msg.output_topic) {
    msg.topic = msg.output_topic;
}

return msg;
